+/** The language for an `Accept-Language` header: the supported one with the highest q, else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  const seen = new Map(); // language (or "*") → { q, at }: its highest q and where it stands
+  header.split(",").forEach((part, at) => {
+    const [range, ...rest] = part.split(";").map((x) => x.trim().toLowerCase());
+    if (!/^(\*|[a-z]{1,8}(-[a-z0-9]{1,8})*)$/.test(range)) return;
+    const qs = rest.filter((x) => /^q\s*=/.test(x)).map((x) => x.replace(/^q\s*=\s*/, ""));
+    if (qs.some((x) => !/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(x))) return;
+    const tag = range.split("-")[0];
+    const q = qs.length ? Number(qs[0]) : 1;
+    if (!seen.has(tag) || q > seen.get(tag).q) seen.set(tag, { q, at });
+  });
+  // "*" stands for every language the header does not name. Highest q wins,
+  // then the one named first, then the fallback.
+  const wish = (lang) => seen.get(lang) ?? seen.get("*") ?? { q: 0, at: 0 };
+  let best = null;
+  for (const lang of [fallback, ...LANGUAGES.filter((l) => l !== fallback)]) {
+    const w = wish(lang);
+    if (w.q > 0 && (!best || w.q > best.q || (w.q === best.q && w.at < best.at))) best = { ...w, lang };
+  }
+  return best ? best.lang : fallback;
 }

